import React, { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import MoonLoader from "react-spinners/MoonLoader";

import "./Upload.css";

function Upload() {
  const [videoFile, setVideoFile] = useState(null);
  const [rubricFile, setRubricFile] = useState(null);
  const [rubricFileName, setRubricFileName] = useState("");
  const [status, setStatus] = useState("");

  const [recording, setRecording] = useState(false);
  const [mediaRecorder, setMediaRecorder] = useState(null);
  const [recordedChunks, setRecordedChunks] = useState([]);
  const [recordedURL, setRecordedURL] = useState("");
  const [stream, setStream] = useState(null);

  const navigate = useNavigate();
  const rubricInputRef = useRef(null);
  const liveVideoRef = useRef(null);

  const handleFileChange = (event) => {
    setVideoFile(event.target.files[0]);
    setRecordedURL("");
  };

  const handleRubricUpload = (event) => {
    const file = event.target.files[0];
    if (file && file.type === "text/plain") {
      setRubricFile(file);
      setRubricFileName(file.name);
    } else {
      console.error("Please upload a valid .txt file.");
    }
  };

  const startRecording = async () => {
    try {
      const userStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      const recorder = new MediaRecorder(userStream);
      setRecordedChunks([]);
      setMediaRecorder(recorder);
      setStream(userStream);
      setRecording(true);

      if (liveVideoRef.current) {
        liveVideoRef.current.srcObject = userStream;
      }

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          setRecordedChunks((prev) => [...prev, e.data]);
        }
      };

      recorder.onstop = () => {
        const blob = new Blob(recordedChunks, { type: "video/webm" });
        const file = new File([blob], `recorded_${Date.now()}.webm`, { type: "video/webm" });
        setVideoFile(file);
        setRecordedURL(URL.createObjectURL(blob));
        userStream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
    } catch (err) {
      alert("Unable to access camera/mic.");
      console.error(err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorder) {
      mediaRecorder.stop();
      setRecording(false);
    }
  };

  const resetRecording = () => {
    setVideoFile(null);
    setRecordedURL("");
    setRecordedChunks([]);
    setRecording(false);
  };

  const handleAnalyze = async () => {
    const userId = localStorage.getItem("user_id");
    if (!userId) {
      alert("You must be logged in to upload and analyze videos.");
      navigate("/login");
      return;
    }

    if (!videoFile) {
      alert("Please upload or record a video first.");
      return;
    }

    setStatus("processing");

    const formData = new FormData();
    formData.append("video", videoFile);
    if (rubricFile) formData.append("rubric", rubricFile);

    try {
      const response = await fetch("http://34.55.142.231:5000/transcribe", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();
      await fetch("http://34.55.142.231:5000/save-video", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: userId,
          video_filename: data.video_filename,
          feedback: data.ai_feedback,
        }),
      });

      navigate("/library");
    } catch (err) {
      console.error("Error uploading:", err);
      setStatus("");
      alert("Upload failed.");
    }
  };

  return (
    <div className="dashboard-container">
      <h1 className="page-title">Video Analysis Dashboard</h1>

      {videoFile && status === "processing" ? (
        <div className="dashboard-content">
          <div className="loader-div">
            <MoonLoader size={50} color="#77232C" />
          </div>
        </div>
      ) : (
        <div className="upload-content">
          <div className="upload-div">
            {recording ? (
              <video ref={liveVideoRef} autoPlay muted width="400" />
            ) : recordedURL ? (
              <video controls width="400">
                <source src={recordedURL} type="video/webm" />
              </video>
            ) : videoFile ? (
              <video controls width="400">
                <source src={URL.createObjectURL(videoFile)} type={videoFile.type} />
              </video>
            ) : (
              <input type="file" accept="video/*" onChange={handleFileChange} />
            )}

            <button className="save-button" onClick={handleAnalyze} disabled={!videoFile}>
              Analyze Video
            </button>

            <div style={{ marginTop: "10px" }}>
              <input
                ref={rubricInputRef}
                type="file"
                accept=".txt"
                style={{ display: "none" }}
                onChange={handleRubricUpload}
              />
              <button className="save-button" type="button" onClick={() => rubricInputRef.current.click()}>
                Upload Rubric
              </button>
            </div>

            {!recording ? (
              <>
                <button className="save-button" onClick={startRecording}>Record Video</button>
                {recordedURL && <button className="save-button" onClick={resetRecording}>Re-record</button>}
              </>
            ) : (
              <button className="save-button" onClick={stopRecording}>Stop Recording</button>
            )}

            {rubricFileName && (
              <p style={{ marginTop: "10px", color: "#77232C", fontWeight: "bold" }}>
                Uploaded Rubric: {rubricFileName}
              </p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default Upload;
